import { createHash } from "node:crypto";

const FORBIDDEN_KEY = /^(?:raw_?prompt|prompt|messages?|body|authorization|api_?key|headers?)$/i;
const SECRET_VALUE_PATTERNS = [
  new RegExp("s" + "k-[A-Za-z0-9_-]{8,}"),
  new RegExp("ph" + "c_[A-Za-z0-9_-]{8,}"),
  new RegExp("gh" + "p_[A-Za-z0-9_-]{8,}"),
  new RegExp("AK" + "IA[A-Z0-9]{12,}"),
  /-----BEGIN(?: [A-Z]+)? PRIVATE KEY-----/
];
const MAX_STRING_LENGTH = 4096;
const MAX_COLLECTION_LENGTH = 256;

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function boundedString(value, label) {
  if (typeof value !== "string" || value.length === 0 || value.length > 512) {
    throw new Error(`${label} must be a non-empty string of at most 512 characters`);
  }
  return value;
}

function canonicalize(value) {
  if (value === null || typeof value === "boolean" || typeof value === "number") return value;
  if (typeof value === "string") return value;
  if (Array.isArray(value)) return value.map(canonicalize);
  if (isPlainObject(value)) {
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map((key) => [key, canonicalize(value[key])])
    );
  }
  throw new Error("trace contains an unsupported value");
}

function jsonDigest(value) {
  const json = JSON.stringify(canonicalize(value));
  return `sha256:${createHash("sha256").update(json, "utf8").digest("hex")}`;
}

function findUnsafeContent(value, trail = "$") {
  if (typeof value === "string") {
    if (value.length > MAX_STRING_LENGTH) {
      return { code: "TRACE_TOO_LARGE", reason: `string at ${trail} exceeds the bound` };
    }
    for (const pattern of SECRET_VALUE_PATTERNS) {
      if (pattern.test(value)) {
        return { code: "UNREDACTED_SECRET", reason: `credential-like value at ${trail}` };
      }
    }
    return null;
  }
  if (Array.isArray(value)) {
    if (value.length > MAX_COLLECTION_LENGTH) {
      return { code: "TRACE_TOO_LARGE", reason: `array at ${trail} exceeds the bound` };
    }
    for (let index = 0; index < value.length; index += 1) {
      const found = findUnsafeContent(value[index], `${trail}[${index}]`);
      if (found) return found;
    }
    return null;
  }
  if (isPlainObject(value)) {
    const keys = Object.keys(value);
    if (keys.length > MAX_COLLECTION_LENGTH) {
      return { code: "TRACE_TOO_LARGE", reason: `object at ${trail} exceeds the bound` };
    }
    for (const key of keys) {
      if (FORBIDDEN_KEY.test(key)) {
        return { code: "UNREDACTED_CONTENT", reason: `forbidden field at ${trail}.${key}` };
      }
      const found = findUnsafeContent(value[key], `${trail}.${key}`);
      if (found) return found;
    }
  }
  return null;
}

function normalizeStatus(trace) {
  const status = String(trace.status ?? trace.outcome ?? trace.result ?? "").toLowerCase();
  if (["failed", "failure", "error", "errored"].includes(status)) return "failed";
  if (["succeeded", "success", "passed", "pass", "rejected", "cancelled", "canceled", "skipped"].includes(status)) {
    return "passed";
  }
  return "unknown";
}

function normalizeReproducer(value) {
  if (!isPlainObject(value)) throw new Error("reproducer must be an object");
  const kind = value.kind;
  if (!["scenario", "route", "command-id"].includes(kind)) {
    throw new Error("reproducer.kind must be scenario, route, or command-id");
  }
  const allowed = kind === "scenario" ? ["kind", "scenario", "scenarioId"] : kind === "route" ? ["kind", "route", "routeId"] : ["kind", "commandId"];
  for (const key of Object.keys(value)) {
    if (!allowed.includes(key)) throw new Error(`reproducer field ${key} is not allowed for ${kind}`);
    if (kind === "command-id" && /command|shell|argv|script/i.test(key)) {
      throw new Error("command-id reproducer must identify a command without shell content");
    }
  }
  const idKey = allowed[1];
  const alternateKey = allowed[2];
  const id = value[idKey] ?? (alternateKey ? value[alternateKey] : undefined);
  const normalized = { kind, [idKey]: boundedString(id, `reproducer.${idKey}`) };
  if (kind === "command-id" && /(?:\s|[;&|`$<>])/.test(normalized.commandId)) {
    throw new Error("command-id must be an opaque identifier");
  }
  return normalized;
}

function rejection(code, reason, trace = {}) {
  return {
    ok: false,
    rejection: {
      code,
      reason,
      runId: typeof trace.runId === "string" ? trace.runId : undefined,
      attempt: Number.isInteger(trace.attempt) ? trace.attempt : undefined
    }
  };
}

/**
 * Converts one already-selected, redacted trace into an immutable replay sample.
 * This function performs no I/O and never mutates the supplied trace.
 */
export function convertTraceToEvalSample(trace) {
  if (!isPlainObject(trace)) return rejection("INVALID_TRACE", "trace must be an object", {});
  const unsafe = findUnsafeContent(trace);
  if (unsafe) return rejection(unsafe.code, unsafe.reason, trace);

  let runId;
  let attempt;
  let selector;
  let reproducer;
  try {
    runId = boundedString(trace.runId, "runId");
    if (!Number.isInteger(trace.attempt) || trace.attempt < 1) throw new Error("attempt must be a positive integer");
    attempt = trace.attempt;
    selector = isPlainObject(trace.selector) ? trace.selector : { runId, attempt };
    if (selector.runId !== runId || selector.attempt !== attempt) {
      throw new Error("selector must bind the supplied runId and attempt");
    }
    reproducer = normalizeReproducer(trace.reproducer);
  } catch (error) {
    return rejection("INVALID_BINDING", error instanceof Error ? error.message : String(error), trace);
  }

  const status = normalizeStatus(trace);
  if (status === "unknown") return rejection("INVALID_STATUS", "trace status must identify failure or non-failure", trace);
  const beforeFix = status === "failed" ? "fail" : "pass";
  const payload = {
    schema: "g03.trace-to-eval-sample.v1",
    source: { runId, attempt, status },
    selector: { runId, attempt },
    reproducer,
    expectations: { beforeFix, afterFix: "pass" }
  };
  return {
    ok: true,
    sample: {
      ...payload,
      digest: jsonDigest(payload)
    }
  };
}

/**
 * Explicitly converts only the traces represented by selected runIds.
 * Each rejected trace gets an independent diagnostic and contributes no sample.
 */
export function convertSelectedTraces(traces, options = {}) {
  if (!Array.isArray(traces)) throw new TypeError("traces must be an array");
  const selectedRunIds = options.runIds === undefined ? null : new Set(options.runIds);
  if (selectedRunIds && [...selectedRunIds].some((id) => typeof id !== "string" || !id)) {
    throw new TypeError("runIds must contain non-empty strings");
  }
  const samples = [];
  const rejected = [];
  for (const trace of traces) {
    if (!isPlainObject(trace)) {
      rejected.push(rejection("INVALID_TRACE", "trace must be an object", {}).rejection);
      continue;
    }
    if (selectedRunIds && !selectedRunIds.has(trace.runId)) continue;
    const result = convertTraceToEvalSample(trace);
    if (result.ok) samples.push(result.sample);
    else rejected.push(result.rejection);
  }
  return { samples, rejected };
}

/** Select recent run IDs without creating any background work. */
export function selectRecentRunIds(traces, options = {}) {
  if (!Array.isArray(traces)) throw new TypeError("traces must be an array");
  const now = options.now instanceof Date ? options.now.getTime() : Date.now();
  const cutoff = now - 7 * 24 * 60 * 60 * 1000;
  const ids = [];
  for (const trace of traces) {
    if (!isPlainObject(trace) || typeof trace.runId !== "string") continue;
    const timestamp = Date.parse(trace.occurredAt ?? trace.timestamp ?? "");
    if (Number.isFinite(timestamp) && timestamp >= cutoff && timestamp <= now) ids.push(trace.runId);
  }
  return [...new Set(ids)].sort();
}

export function isTraceSafeForEval(trace) {
  return findUnsafeContent(trace) === null;
}

export function digestEvalSample(sample) {
  if (!isPlainObject(sample)) throw new TypeError("sample must be an object");
  const { digest, ...payload } = sample;
  return jsonDigest(payload);
}

export const traceToEvalSample = convertTraceToEvalSample;
export const traceToEvalSamples = convertSelectedTraces;

export type EvalReproducer =
  | { kind: "scenario"; scenario: string }
  | { kind: "route"; route: string }
  | { kind: "command-id"; commandId: string };

export interface TraceSelector {
  runId: string;
  attempt: number;
}

export interface EvalTrace {
  runId: string;
  attempt: number;
  status?: string;
  outcome?: string;
  result?: string;
  occurredAt?: string;
  timestamp?: string;
  selector?: TraceSelector;
  reproducer: EvalReproducer;
  [key: string]: unknown;
}

export interface EvalSample {
  schema: "g03.trace-to-eval-sample.v1";
  source: { runId: string; attempt: number; status: "failed" | "passed" };
  selector: TraceSelector;
  reproducer: EvalReproducer;
  expectations: { beforeFix: "fail" | "pass"; afterFix: "pass" };
  digest: string;
}

export interface TraceRejection {
  code:
    | "INVALID_TRACE"
    | "INVALID_BINDING"
    | "INVALID_STATUS"
    | "UNREDACTED_CONTENT"
    | "UNREDACTED_SECRET"
    | "TRACE_TOO_LARGE";
  reason: string;
  runId?: string;
  attempt?: number;
}

export type TraceConversionResult =
  | { ok: true; sample: EvalSample }
  | { ok: false; rejection: TraceRejection };

export interface SelectedTraceConversionResult {
  samples: EvalSample[];
  rejected: TraceRejection[];
}

export function convertTraceToEvalSample(trace: EvalTrace): TraceConversionResult;
export function convertSelectedTraces(
  traces: readonly EvalTrace[],
  options?: { runIds?: readonly string[] }
): SelectedTraceConversionResult;
export function selectRecentRunIds(
  traces: readonly EvalTrace[],
  options?: { now?: Date }
): string[];
export function isTraceSafeForEval(trace: unknown): boolean;
export function digestEvalSample(sample: EvalSample): string;

export const traceToEvalSample: typeof convertTraceToEvalSample;
export const traceToEvalSamples: typeof convertSelectedTraces;

