const FORBIDDEN_KEY = /^(?:raw_?prompt|prompt|messages?|body|authorization|api_?key|headers?)$/i;
const SECRET_VALUE_PATTERNS = [
  new RegExp("s" + "k-[A-Za-z0-9_-]{8,}"),
  new RegExp("ph" + "c_[A-Za-z0-9_-]{8,}"),
  new RegExp("gh" + "p_[A-Za-z0-9_-]{8,}"),
  new RegExp("AK" + "IA[A-Z0-9]{12,}"),
  /-----BEGIN(?: [A-Z]+)? PRIVATE KEY-----/
];
const MAX_STRING_LENGTH = 4096;
const MAX_COLLECTION_LENGTH = 256;

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function boundedString(value, label) {
  if (typeof value !== "string" || value.length === 0 || value.length > 512) {
    throw new Error(`${label} must be a non-empty string of at most 512 characters`);
  }
  return value;
}

function canonicalize(value) {
  if (value === null || typeof value === "boolean" || typeof value === "number") return value;
  if (typeof value === "string") return value;
  if (Array.isArray(value)) return value.map(canonicalize);
  if (isPlainObject(value)) {
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map((key) => [key, canonicalize(value[key])])
    );
  }
  throw new Error("trace contains an unsupported value");
}

function jsonDigest(value) {
  const json = JSON.stringify(canonicalize(value));
  return `sha256:${createHash("sha256").update(json, "utf8").digest("hex")}`;
}

function findUnsafeContent(value, trail = "$") {
  if (typeof value === "string") {
    if (value.length > MAX_STRING_LENGTH) {
      return { code: "TRACE_TOO_LARGE", reason: `string at ${trail} exceeds the bound` };
    }
    for (const pattern of SECRET_VALUE_PATTERNS) {
      if (pattern.test(value)) {
        return { code: "UNREDACTED_SECRET", reason: `credential-like value at ${trail}` };
      }
    }
    return null;
  }
  if (Array.isArray(value)) {
    if (value.length > MAX_COLLECTION_LENGTH) {
      return { code: "TRACE_TOO_LARGE", reason: `array at ${trail} exceeds the bound` };
    }
    for (let index = 0; index < value.length; index += 1) {
      const found = findUnsafeContent(value[index], `${trail}[${index}]`);
      if (found) return found;
    }
    return null;
  }
  if (isPlainObject(value)) {
    const keys = Object.keys(value);
    if (keys.length > MAX_COLLECTION_LENGTH) {
      return { code: "TRACE_TOO_LARGE", reason: `object at ${trail} exceeds the bound` };
    }
    for (const key of keys) {
      if (FORBIDDEN_KEY.test(key)) {
        return { code: "UNREDACTED_CONTENT", reason: `forbidden field at ${trail}.${key}` };
      }
      const found = findUnsafeContent(value[key], `${trail}.${key}`);
      if (found) return found;
    }
  }
  return null;
}

function normalizeStatus(trace) {
  const status = String(trace.status ?? trace.outcome ?? trace.result ?? "").toLowerCase();
  if (["failed", "failure", "error", "errored"].includes(status)) return "failed";
  if (["succeeded", "success", "passed", "pass", "rejected", "cancelled", "canceled", "skipped"].includes(status)) {
    return "passed";
  }
  return "unknown";
}

function normalizeReproducer(value) {
  if (!isPlainObject(value)) throw new Error("reproducer must be an object");
  const kind = value.kind;
  if (!["scenario", "route", "command-id"].includes(kind)) {
    throw new Error("reproducer.kind must be scenario, route, or command-id");
  }
  const allowed = kind === "scenario" ? ["kind", "scenario", "scenarioId"] : kind === "route" ? ["kind", "route", "routeId"] : ["kind", "commandId"];
  for (const key of Object.keys(value)) {
    if (!allowed.includes(key)) throw new Error(`reproducer field ${key} is not allowed for ${kind}`);
    if (kind === "command-id" && /command|shell|argv|script/i.test(key)) {
      throw new Error("command-id reproducer must identify a command without shell content");
    }
  }
  const idKey = allowed[1];
  const alternateKey = allowed[2];
  const id = value[idKey] ?? (alternateKey ? value[alternateKey] : undefined);
  const normalized = { kind, [idKey]: boundedString(id, `reproducer.${idKey}`) };
