    throw new Error("command-id must be an opaque identifier");
  }
  return normalized;
}

function rejection(code, reason, trace = {}) {
  return {
    ok: false,
    rejection: {
      code,
      reason,
      runId: typeof trace.runId === "string" ? trace.runId : undefined,
      attempt: Number.isInteger(trace.attempt) ? trace.attempt : undefined
    }
  };
}

/**
 * Converts one already-selected, redacted trace into an immutable replay sample.
 * This function performs no I/O and never mutates the supplied trace.
 */
export function convertTraceToEvalSample(trace) {
  if (!isPlainObject(trace)) return rejection("INVALID_TRACE", "trace must be an object", {});
  const unsafe = findUnsafeContent(trace);
  if (unsafe) return rejection(unsafe.code, unsafe.reason, trace);

  let runId;
  let attempt;
  let selector;
  let reproducer;
  try {
    runId = boundedString(trace.runId, "runId");
    if (!Number.isInteger(trace.attempt) || trace.attempt < 1) throw new Error("attempt must be a positive integer");
    attempt = trace.attempt;
    selector = isPlainObject(trace.selector) ? trace.selector : { runId, attempt };
    if (selector.runId !== runId || selector.attempt !== attempt) {
      throw new Error("selector must bind the supplied runId and attempt");
    }
    reproducer = normalizeReproducer(trace.reproducer);
  } catch (error) {
    return rejection("INVALID_BINDING", error instanceof Error ? error.message : String(error), trace);
  }

  const status = normalizeStatus(trace);
  if (status === "unknown") return rejection("INVALID_STATUS", "trace status must identify failure or non-failure", trace);
  const beforeFix = status === "failed" ? "fail" : "pass";
  const payload = {
    schema: "g03.trace-to-eval-sample.v1",
    source: { runId, attempt, status },
    selector: { runId, attempt },
    reproducer,
    expectations: { beforeFix, afterFix: "pass" }
  };
  return {
    ok: true,
    sample: {
      ...payload,
      digest: jsonDigest(payload)
    }
  };
}

/**
 * Explicitly converts only the traces represented by selected runIds.
 * Each rejected trace gets an independent diagnostic and contributes no sample.
 */
export function convertSelectedTraces(traces, options = {}) {
  if (!Array.isArray(traces)) throw new TypeError("traces must be an array");
  const selectedRunIds = options.runIds === undefined ? null : new Set(options.runIds);
  if (selectedRunIds && [...selectedRunIds].some((id) => typeof id !== "string" || !id)) {
    throw new TypeError("runIds must contain non-empty strings");
  }
  const samples = [];
  const rejected = [];
  for (const trace of traces) {
    if (!isPlainObject(trace)) {
      rejected.push(rejection("INVALID_TRACE", "trace must be an object", {}).rejection);
      continue;
    }
    if (selectedRunIds && !selectedRunIds.has(trace.runId)) continue;
    const result = convertTraceToEvalSample(trace);
    if (result.ok) samples.push(result.sample);
    else rejected.push(result.rejection);
  }
  return { samples, rejected };
}

/** Select recent run IDs without creating any background work. */
export function selectRecentRunIds(traces, options = {}) {
  if (!Array.isArray(traces)) throw new TypeError("traces must be an array");
  const now = options.now instanceof Date ? options.now.getTime() : Date.now();
  const cutoff = now - 7 * 24 * 60 * 60 * 1000;
  const ids = [];
  for (const trace of traces) {
    if (!isPlainObject(trace) || typeof trace.runId !== "string") continue;
    const timestamp = Date.parse(trace.occurredAt ?? trace.timestamp ?? "");
    if (Number.isFinite(timestamp) && timestamp >= cutoff && timestamp <= now) ids.push(trace.runId);
  }
  return [...new Set(ids)].sort();
}

export function isTraceSafeForEval(trace) {
  return findUnsafeContent(trace) === null;
}

export function digestEvalSample(sample) {
  if (!isPlainObject(sample)) throw new TypeError("sample must be an object");
  const { digest, ...payload } = sample;
  return jsonDigest(payload);
}

export const traceToEvalSample = convertTraceToEvalSample;
export const traceToEvalSamples = convertSelectedTraces;
