  | { kind: "scenario"; scenario: string }
  | { kind: "route"; route: string }
  | { kind: "command-id"; commandId: string };

export interface TraceSelector {
  runId: string;
  attempt: number;
}

export interface EvalTrace {
  runId: string;
  attempt: number;
  status?: string;
  outcome?: string;
  result?: string;
  occurredAt?: string;
  timestamp?: string;
  selector?: TraceSelector;
  reproducer: EvalReproducer;
  [key: string]: unknown;
}

export interface EvalSample {
  schema: "g03.trace-to-eval-sample.v1";
  source: { runId: string; attempt: number; status: "failed" | "passed" };
  selector: TraceSelector;
  reproducer: EvalReproducer;
  expectations: { beforeFix: "fail" | "pass"; afterFix: "pass" };
  digest: string;
}

export interface TraceRejection {
  code:
    | "INVALID_TRACE"
    | "INVALID_BINDING"
    | "INVALID_STATUS"
    | "UNREDACTED_CONTENT"
    | "UNREDACTED_SECRET"
    | "TRACE_TOO_LARGE";
  reason: string;
  runId?: string;
  attempt?: number;
}

export type TraceConversionResult =
  | { ok: true; sample: EvalSample }
  | { ok: false; rejection: TraceRejection };

export interface SelectedTraceConversionResult {
  samples: EvalSample[];
  rejected: TraceRejection[];
}

export function convertTraceToEvalSample(trace: EvalTrace): TraceConversionResult;
export function convertSelectedTraces(
  traces: readonly EvalTrace[],
  options?: { runIds?: readonly string[] }
): SelectedTraceConversionResult;
export function selectRecentRunIds(
  traces: readonly EvalTrace[],
  options?: { now?: Date }
): string[];
export function isTraceSafeForEval(trace: unknown): boolean;
export function digestEvalSample(sample: EvalSample): string;

export const traceToEvalSample: typeof convertTraceToEvalSample;
export const traceToEvalSamples: typeof convertSelectedTraces;
