    source: { runId, attempt, status },
    selector: { runId, attempt },
    reproducer,
    expectations: { beforeFix, afterFix: "pass" }
  };
  return {
    ok: true,
    sample: {
      ...payload,
      digest: jsonDigest(payload)
    }
  };
