const FORBIDDEN_KEY = /^(?:raw_?prompt|prompt|messages?|body|authorization|api_?key|headers?)$/i;
const SECRET_VALUE_PATTERNS = [
  new RegExp("s" + "k-[A-Za-z0-9_-]{8,}"),
  new RegExp("ph" + "c_[A-Za-z0-9_-]{8,}"),
  new RegExp("gh" + "p_[A-Za-z0-9_-]{8,}"),
  new RegExp("AK" + "IA[A-Z0-9]{12,}"),
  /-----BEGIN(?: [A-Z]+)? PRIVATE KEY-----/
];
const MAX_STRING_LENGTH = 4096;
const MAX_COLLECTION_LENGTH = 256;

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function boundedString(value, label) {
  if (typeof value !== "string" || value.length === 0 || value.length > 512) {
    throw new Error(`${label} must be a non-empty string of at most 512 characters`);
  }
  return value;
}

function canonicalize(value) {
  if (value === null || typeof value === "boolean" || typeof value === "number") return value;
  if (typeof value === "string") return value;
  if (Array.isArray(value)) return value.map(canonicalize);
  if (isPlainObject(value)) {
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map((key) => [key, canonicalize(value[key])])
    );
  }
  throw new Error("trace contains an unsupported value");
}

function jsonDigest(value) {
  const json = JSON.stringify(canonicalize(value));
  return `sha256:${createHash("sha256").update(json, "utf8").digest("hex")}`;
}

function findUnsafeContent(value, trail = "$") {
