    for (const key of keys) {
      if (FORBIDDEN_KEY.test(key)) {
        return { code: "UNREDACTED_CONTENT", reason: `forbidden field at ${trail}.${key}` };
      }
      const found = findUnsafeContent(value[key], `${trail}.${key}`);
      if (found) return found;
